/* POC VII: optional questions, permanent run unlocks, active-play respawns. */
(()=>{'use strict';
const $=s=>document.querySelector(s),FLOOR=421,WIDTH=3300,C={1:0xd6e8ef,3:0xc4f2af,4:0xb7d9ff};
const held={left:new Set(),right:new Set(),fire:new Set()},events=[],p={x:135,y:FLOOR,vy:0,ground:true,face:1,inv:0,fire:0,land:0};
const drops=[{x:850,n:3,status:'ready',attempt:0},{x:1820,n:4,status:'ready',attempt:0}];
const platforms=[{x:440,y:347,w:180},{x:1100,y:332,w:175},{x:1430,y:350,w:150},{x:2150,y:338,w:190},{x:2630,y:349,w:210}];
let scene,mode='intro',active=0,clock=0,health=5,weapon=1,auto=false,unlocked={1:true,3:false,4:false},question=null,near=null,checkpoint=135,completed=false;
let jump=false,fireQueued=false,openQueued=false,fireCD=0,noticeUntil=0,shots=[],particles=[],audio,hitStop=0;
function log(type,data={}){events.push({type,active:+active.toFixed(3),...data})}
function sound(f=400,d=.12){try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.5,audio.currentTime+d);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function burst(x,y,c,count=15){for(let i=0;i<count;i++){let a=Math.random()*Math.PI*2,v=35+Math.random()*145;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.3+Math.random()*.55,c})}}
function say(t,seconds=2){$('#notice').textContent=t;noticeUntil=clock+seconds}
function clear(){Object.values(held).forEach(s=>s.clear());jump=fireQueued=openQueued=false}
function hud(){for(let n of[1,3,4]){$('#w'+n).disabled=!unlocked[n];$('#w'+n).classList.toggle('on',weapon===n)}$('#hearts').textContent='♥'.repeat(health)+'♡'.repeat(5-health);$('#auto small').textContent='AUTO '+(auto?'ON':'OFF');$('#auto').setAttribute('aria-pressed',auto);$('#auto').classList.toggle('on',auto);$('#controls').hidden=mode!=='play';$('#pause').disabled=mode!=='play'&&mode!=='paused';$('#nearby').hidden=mode!=='play'||!near;if(near)$('#drop-name').textContent='OPTIONAL · ×'+near.n+' SHOT';}
function select(n){if(mode==='play'&&unlocked[n]){weapon=n;sound(300+n*100);hud();log('weapon',{weapon:n})}}
function pause(){if(mode==='play'){mode='paused';clear();$('#paused').hidden=false;log('pause')}else if(mode==='paused'){mode='play';$('#paused').hidden=true;log('resume')}hud()}
function fact(d){return [4,7,2,9,5,10,3,8,6,1][(d.attempt+(d.n===4?2:0))%10]}
function openDrop(d){if(mode!=='play'||d.status!=='ready'||Math.abs(p.x-d.x)>145)return;question={drop:d,n:d.n,value:fact(d)};mode='question';clear();$('#question').hidden=false;$('#reward').textContent='UNLOCK ×'+d.n+' SHOT';$('#equation').textContent=d.n+' × '+question.value+' = ?';let correct=d.n*question.value,values=[correct,correct+d.n,correct> d.n?correct-d.n:correct+1];for(let i=values.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]]}$('#answers').replaceChildren();for(let v of values){let b=document.createElement('button');b.textContent=v;b.onclick=()=>answer(v);$('#answers').append(b)}sound(780,.16);hud();log('question',{factor:d.n,value:question.value,attempt:d.attempt})}
function leave(){if(mode!=='question')return;question=null;mode='play';$('#question').hidden=true;clear();fireCD=.25;hud();log('question-left')}
function answer(v){if(mode!=='question')return;let q=question,d=q.drop,correct=v===q.n*q.value;question=null;mode='play';$('#question').hidden=true;clear();fireCD=.3;if(correct){unlocked[d.n]=true;weapon=d.n;d.status='earned';burst(d.x,300,C[d.n],60);burst(p.x,p.y-45,C[d.n],35);sound(1046,.4);scene.cameras.main.flash(130,145,180,135);say('×'+d.n+' SHOT UNLOCKED!',2.5);log('unlock',{factor:d.n})}else{d.status='cooldown';d.readyAt=active+20;d.attempt++;burst(d.x,300,0x859db3,18);sound(150,.14);say('Keep going!',1);log('wrong',{factor:d.n,readyAt:d.readyAt})}near=null;hud()}
for(let id of['left','right','fire']){let el=$('#'+id);el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);if(mode!=='play')return;held[id].add(e.pointerId);if(id==='fire')fireQueued=true;sound(100,.02)};el.onpointerup=el.onpointercancel=e=>held[id].delete(e.pointerId)}
$('#jump').onpointerdown=e=>{e.preventDefault();if(mode==='play')jump=true};$('#open').onclick=()=>{if(near)openDrop(near)};for(let n of[1,3,4])$('#w'+n).onclick=()=>select(n);$('#auto').onclick=()=>{if(mode==='play'){auto=!auto;hud()}};$('#pause').onclick=$('#resume').onclick=pause;$('#close').onclick=$('#skip').onclick=leave;$('#enter-boss').onclick=()=>location.assign('boss.html');$('#restart').onclick=()=>location.reload();$('#explore').onclick=()=>{mode='play';$('#finish').hidden=true;hud()};$('#start').onclick=()=>{mode='play';$('#intro').hidden=true;sound(600);say('Reach the vault →',3);hud();log('start')};
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','f','e','q','1','3','4','Escape'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='Escape'){if(mode==='question')leave();else pause();return}if(mode!=='play')return;if(['a','ArrowLeft'].includes(e.key))held.left.add('key');if(['d','ArrowRight'].includes(e.key))held.right.add('key');if(['w','ArrowUp',' '].includes(e.key))jump=true;if(e.key==='f'){held.fire.add('key');fireQueued=true}if(e.key==='e')openQueued=true;if(['1','3','4'].includes(e.key))select(+e.key);if(e.key==='q')$('#auto').click()});addEventListener('keyup',e=>{if(['a','ArrowLeft'].includes(e.key))held.left.delete('key');if(['d','ArrowRight'].includes(e.key))held.right.delete('key');if(e.key==='f')held.fire.delete('key')});addEventListener('blur',()=>{clear();if(mode==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clear();if(mode==='play')pause()}});
function resize(){let b=getComputedStyle(document.body),l=parseFloat(b.paddingLeft)||0,r=parseFloat(b.paddingRight)||0,t=parseFloat(b.paddingTop)||0,bot=parseFloat(b.paddingBottom)||0,w=innerWidth-l-r,h=innerHeight-t-bot;$('#stage').style.cssText=`left:${l+w/2}px;top:${t+h/2}px;transform:translate(-50%,-50%) scale(${Math.min(w/960,h/540)})`}addEventListener('resize',resize);if(window.visualViewport)visualViewport.addEventListener('resize',resize);resize();
function hurt(){if(p.inv>0)return;health--;p.inv=1.7;burst(p.x,p.y-45,0xffb8a2);sound(110,.2);scene.cameras.main.shake(100,.003);log('hurt',{health});if(health<=0){p.x=checkpoint;p.y=FLOOR;p.vy=0;health=5;shots=[];say('Back on your feet!',1.5);log('checkpoint',{unlocked:{...unlocked}})}hud()}
class Trail extends Phaser.Scene{
 preload(){this.load.image('bg','../assets/observatory.png');this.load.image('platform','../assets/platform.png');this.load.image('core','../assets/core.png');this.load.spritesheet('dragon','../assets/dragon.png',{frameWidth:128,frameHeight:128});this.load.spritesheet('guardian','../assets/guardian.png',{frameWidth:256,frameHeight:256});this.load.on('loaderror',()=>$('#loading').textContent='Could not load. Refresh to retry.');}
 create(){scene=this;this.cameras.main.setBounds(0,0,WIDTH,540);this.bg=this.add.tileSprite(480,270,960,540,'bg').setTileScale(2).setScrollFactor(0);this.back=this.add.graphics();for(let x=0;x<WIDTH;x+=240)this.add.image(x,FLOOR,'platform').setOrigin(0).setDisplaySize(242,47).setTint(0x7991a3);for(let q of platforms)this.add.image(q.x,q.y,'platform').setOrigin(0).setDisplaySize(q.w,24);this.g=this.add.graphics().setDepth(3);this.hero=this.add.sprite(p.x,p.y+7,'dragon',6).setOrigin(.5,1).setDisplaySize(140,140).setDepth(5);this.fx=this.add.graphics().setDepth(7);this.enemies=[{x:520,hp:2},{x:1240,hp:3},{x:1570,hp:3},{x:2150,hp:5},{x:2470,hp:5},{x:2860,hp:6}].map((e,i)=>({...e,max:e.hp,home:e.x,y:382,phase:i*1.7,hit:0,dead:0,sprite:this.add.sprite(e.x,390,'guardian',0).setDisplaySize(100,100).setDepth(4)}));
 for(let d of drops){d.sprite=this.add.image(d.x,300,'core').setDisplaySize(44,44).setTint(C[d.n]).setDepth(5).setInteractive({useHandCursor:true});d.sprite.on('pointerdown',()=>openDrop(d));d.label=this.add.text(d.x,248,'×'+d.n+' SHOT',{fontFamily:'monospace',fontSize:17,color:'#e7edc4',stroke:'#081422',strokeThickness:5}).setOrigin(.5).setDepth(6);this.add.text(d.x,325,'OPTIONAL',{fontFamily:'monospace',fontSize:10,color:'#b4c8cf',stroke:'#081422',strokeThickness:4}).setOrigin(.5).setDepth(2)}this.beacon=this.add.image(3110,286,'core').setDisplaySize(55,55).setDepth(3);this.add.text(3110,210,'CORE CLASH →',{fontFamily:'monospace',fontSize:22,color:'#e7efc7',stroke:'#081422',strokeThickness:5}).setOrigin(.5);this.pickups=[1050,2030,2720].map(x=>({x,taken:false,sprite:this.add.image(x,376,'core').setDisplaySize(20,20).setTint(0xffb7a9)}));$('#loading').hidden=true;hud();window.gameState=()=>({mode,x:p.x,y:p.y,active,weapon,unlocked:{...unlocked},health,checkpoint,auto,completed,question:question?{factor:question.n,value:question.value}:null,drops:drops.map(d=>({x:d.x,n:d.n,status:d.status,attempt:d.attempt,readyAt:d.readyAt})),enemies:this.enemies.map(e=>({x:e.x,hp:e.hp})),shots:shots.length});window.pocEvents=()=>events.slice();log('ready');}
 shoot(){fireCD=.32;p.fire=.13;let candidates=this.enemies.filter(e=>e.hp>0&&(e.x-p.x)*p.face>0&&Math.abs(e.x-p.x)<530).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x)),target=candidates[0],x=p.x+p.face*43,y=p.y-46,tx=target?target.x:x+p.face*800,ty=target?target.y:y,dx=tx-x,dy=ty-y,len=Math.hypot(dx,dy);shots.push({x,y,vx:dx/len*770,vy:dy/len*770,n:weapon,life:1.2});burst(x,y,C[weapon],weapon===1?5:12);sound(weapon===1?410:180,.08);log('shot',{weapon,damage:weapon})}
 update(_,delta){const dt=Math.min(delta/1000,.033);if(mode==='play'){active+=dt;clock+=dt;if(hitStop>0)hitStop-=dt;else this.step(dt)}this.draw(mode==='play'?dt:0);}
 step(dt){if(clock>noticeUntil)$('#notice').textContent='';p.inv=Math.max(0,p.inv-dt);p.fire=Math.max(0,p.fire-dt);p.land=Math.max(0,p.land-dt);let dir=+!!held.right.size-+!!held.left.size;if(dir)p.face=dir;p.x=Phaser.Math.Clamp(p.x+dir*265*dt,65,WIDTH-85);if(jump&&p.ground){p.vy=-470;p.ground=false;sound(540);burst(p.x,p.y,0x9bb1c1,6);log('jump')}jump=false;const old=p.y;p.vy+=1150*dt;p.y+=p.vy*dt;p.ground=false;let floor=FLOOR;for(let q of platforms)if(p.x>q.x-8&&p.x<q.x+q.w+8&&old<=q.y+3&&p.y>=q.y&&p.vy>=0)floor=Math.min(floor,q.y);if(p.y>=floor){if(p.vy>180){p.land=.12;burst(p.x,floor,0x8da2b5,8)}p.y=floor;p.vy=0;p.ground=true}
 for(let d of drops)if(d.status==='cooldown'&&active>=d.readyAt){d.status='ready';burst(d.x,300,C[d.n],24);sound(830,.22);say('✦ A knowledge drop glows again',2);log('respawn',{factor:d.n})}near=drops.find(d=>d.status==='ready'&&Math.abs(d.x-p.x)<145)||null;if(openQueued){openQueued=false;if(near){openDrop(near);return}}fireCD-=dt;if((held.fire.size||auto||fireQueued)&&fireCD<=0){this.shoot();fireQueued=false}
 for(let e of this.enemies){e.hit=Math.max(0,e.hit-dt);if(e.hp<=0){e.dead+=dt;continue}e.x=e.home+Math.sin(clock*1.3+e.phase)*38;e.y=383+Math.sin(clock*2+e.phase)*4;if(Math.abs(p.x-e.x)<40&&Math.abs(p.y-38-e.y)<49)hurt()}
 for(let s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let e=this.enemies.find(e=>e.hp>0&&Math.hypot(s.x-e.x,s.y-e.y)<36);if(e){e.hp=Math.max(0,e.hp-s.n);e.hit=.17;s.life=0;hitStop=s.n>1?.04:.015;burst(e.x,e.y,C[s.n],s.n>1?26:12);sound(120,.1);if(s.n>1)this.cameras.main.shake(65,.0018);log('hit',{weapon:s.n,hp:e.hp});if(!e.hp)burst(e.x,e.y,0xffe4ae,30)}}shots=shots.filter(s=>s.life>0);
 for(let h of this.pickups)if(!h.taken&&Math.abs(p.x-h.x)<28&&p.y>340){h.taken=true;h.sprite.setVisible(false);health=Math.min(5,health+1);burst(h.x,376,0xffb7a9,15);sound(730)}if(p.x>1400&&checkpoint<1400){checkpoint=1410;health=5}if(p.x>2350&&checkpoint<2350){checkpoint=2360;health=5}if(p.x>3070&&!completed){completed=true;mode='finish';clear();$('#finish').hidden=false;$('#finish-copy').textContent='The guardian is waiting.'+(!unlocked[3]||!unlocked[4]?' You can still go back for the knowledge drops.':' Both stronger shots are yours.');burst(3110,280,0xe3f4bd,65);sound(1046,.4);log('finish',{unlocked:{...unlocked}})}hud();this.cameras.main.scrollX=Phaser.Math.Linear(this.cameras.main.scrollX,Phaser.Math.Clamp(p.x-320,0,WIDTH-960),.1);}
 draw(dt){let g=this.g,f=this.fx,t=clock;g.clear();f.clear();this.bg.tilePositionX=this.cameras.main.scrollX*.18;for(let x=250;x<WIDTH;x+=590){g.fillStyle(0x0a1724,.9);g.fillRect(x,384,8,37);g.fillStyle(0xffdda0,.12);g.fillCircle(x+4,379,23);g.fillStyle(0xf4dfa4);g.fillRect(x,373,8,12)}let fr=p.land>0?10:!p.ground?(p.vy<0?7:8):p.fire>0?9:held.left.size||held.right.size?Math.floor(t*12)%6:6;this.hero.setPosition(p.x,p.y+7+(fr===6?Math.sin(t*3):0)).setFrame(fr).setFlipX(p.face<0).setAlpha(p.inv>0&&Math.floor(t*15)%2?.45:1);
 for(let d of drops){let visible=d.status==='ready';d.sprite.setVisible(visible).setY(297+Math.sin(t*2.5)*7);d.label.setText(d.status==='earned'?'UNLOCKED':'×'+d.n+' SHOT').setAlpha(d.status==='cooldown'?.28:d.status==='earned'?.5:1);g.fillStyle(0x192c3d);g.fillRect(d.x-28,345,56,13);g.fillStyle(0x759394);g.fillRect(d.x-31,342,62,4);if(visible){g.lineStyle(1,C[d.n],.6);g.strokeEllipse(d.x,300,70,53);g.fillStyle(C[d.n],.06);g.fillCircle(d.x,300,43);for(let i=0;i<4;i++){let a=t*1.7+i*Math.PI/2;g.fillStyle(C[d.n],.8);g.fillRect(d.x+Math.cos(a)*34,300+Math.sin(a)*24,3,3)}}}
 for(let e of this.enemies){e.sprite.setPosition(e.x,e.y).setFrame(e.hp<=0?(e.dead<.18?5:e.dead<.5?6:7):e.hit>0?5:Math.sin(t*2+e.phase)>.7?1:0).setAlpha(e.hp<=0?Math.max(0,1-e.dead*1.8):1);if(e.hp>0){g.fillStyle(0x0b1322);g.fillRect(e.x-22,e.y-50,44,5);g.fillStyle(0xe5b68a);g.fillRect(e.x-21,e.y-49,42*e.hp/e.max,3)}}
 g.lineStyle(6,0x759b97,.7);g.strokeRoundedRect(3066,238,88,182,36);g.lineStyle(2,0xc6e9ac,.8);g.strokeRoundedRect(3074,247,72,174,30);g.fillStyle(0xbde8b8,.06);g.fillRect(3077,280,66,140);this.beacon.setY(284+Math.sin(t*2)*7);
 for(let s of shots){f.lineStyle(s.n===1?3:7,C[s.n]);f.lineBetween(s.x-s.vx*.028,s.y-s.vy*.028,s.x,s.y);f.fillStyle(0xfff3d2);f.fillCircle(s.x,s.y,s.n===1?2:4);if(s.n>1){f.lineStyle(1,C[s.n],.7);f.strokeCircle(s.x,s.y,s.n===3?8:11)}}if(p.fire>0){f.fillStyle(C[weapon]);f.fillTriangle(p.x+p.face*42,p.y-57,p.x+p.face*64,p.y-46,p.x+p.face*42,p.y-36)}for(let q of particles){q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=160*dt;f.fillStyle(q.c,Math.max(0,q.life));f.fillRect(q.x,q.y,3,3)}particles=particles.filter(q=>q.life>0);for(let i=0;i<25;i++){let x=this.cameras.main.scrollX+(i*93+t*7)%960,y=160+i*53%245;f.fillStyle(0xc4e6d6,.3);f.fillRect(x,y,2,2)}}
}
new Phaser.Game({type:Phaser.AUTO,width:960,height:540,parent:'world',pixelArt:true,roundPixels:true,backgroundColor:'#0b1829',audio:{noAudio:true},scene:Trail,banner:false});
})();
